47   // An overly long address type lets us define functions that work generically for shorter
48   // addresses.  We rely on the synthesizer to optimize the unused bits away.
49   typedef logic [127:0] largest_addr_t;
50 
51   // Aligned address of burst (see A3-51).
52   function automatic largest_addr_t aligned_addr(largest_addr_t addr, size_t size);
53     return (addr >> size) << size;
54   endfunction
